sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartEnd = null;

    $scope.anoSelecionadoEnd = "";
    $scope.exibirGraficoEnd = false;

    var coresEnd = {
        apurado: '#a7b9e8',
        meta: '#4b77bf'
    };

    /**
     * Função para carregar os dados do servidor com filtro de ano
     */
    function carregarDadosEndFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoEnd || ""
        };
        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoEnd || [];
            var anosDisponiveis = response.data.anos || [];

            // --- ALTERAÇÃO: VERIFICAÇÃO DE BIBLIOTECA ---
            // Substituímos o $timeout direto pela função que garante que o Chart existe
            verificarBibliotecaChart(function() {
                montarGraficoEnd(dados, anosDisponiveis);
            });
        });
    }

    /**
     * --- NOVA FUNÇÃO DE SEGURANÇA ---
     * Verifica se a biblioteca Chart.js já foi carregada.
     */
    function verificarBibliotecaChart(callbackSucesso) {
        if (typeof Chart !== 'undefined') {
            callbackSucesso();
        } else {
            // Se ainda não carregou, espera 500ms e tenta de novo
            $timeout(function() {
                verificarBibliotecaChart(callbackSucesso);
            }, 500);
        }
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoEnd = ano;
        carregarDadosEndFiltrado();
    });

    carregarDadosEndFiltrado();

    function montarGraficoEnd(listaDados, anosDisponiveis) {

        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        if (anosPresentes.length === 0) {
            if (chartEnd) {
                chartEnd.destroy();
                chartEnd = null;
            }
            $scope.exibirGraficoEnd = false;
            // Segurança para atualizar a view
            $scope.$applyAsync();
            return;
        }
        $scope.exibirGraficoEnd = true;
        // Segurança para atualizar a view antes de desenhar
        $scope.$applyAsync();

        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.apurado) : null;
        });
        var dadosMeta = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.meta) : null;
        });

        // ------------------------
        // ESCALA DINÂMICA (mil, mi, bi)
        // ------------------------
        var todosValores = dadosApurado.concat(dadosMeta).filter(function(v) {
            return v !== null && !isNaN(v);
        });

        var maxAbs = 0;
        if (todosValores.length > 0) {
            var maxVal = Math.max.apply(null, todosValores);
            var minVal = Math.min.apply(null, todosValores);
            maxAbs = Math.max(Math.abs(maxVal), Math.abs(minVal));
        }

        var unidadeEscala = '';
        var divisorEscala = 1;

        if (maxAbs >= 1e9) {
            unidadeEscala = ' bi';
            divisorEscala = 1e9;
        } else if (maxAbs >= 1e6) {
            unidadeEscala = ' mi';
            divisorEscala = 1e6;
        } else if (maxAbs >= 1e3) {
            unidadeEscala = ' mil';
            divisorEscala = 1e3;
        }

        // ------------------------
        // ESCALA Y (usa o seu padding fixo)
        // ------------------------
        var maxVal = todosValores.length > 0 ? Math.max.apply(null, todosValores) : 100;
        var minVal = todosValores.length > 0 ? Math.min.apply(null, todosValores) : 0;

        var PADDING_FIXO = 100; // Cuidado: Se os valores forem bilhões, padding de 100 pode ser invisível

        // Ajuste defensivo: Se a escala for muito grande, o padding fixo de 100 pode não surtir efeito.
        // Mas mantive sua lógica original abaixo:
        var scaleMax;
        var scaleMin;

        if (maxVal === 0 && minVal === 0) {
            scaleMax = 10;
            scaleMin = -10;
        } else {
            scaleMax = maxVal + PADDING_FIXO;
            scaleMin = minVal - PADDING_FIXO;

            if (minVal >= 0 && scaleMin < 0) {
                scaleMin = 0;
            }
        }

        var desiredType = 'bar';

        var datasets = [{
            label: 'Valor Apurado',
            data: dadosApurado,
            backgroundColor: coresEnd.apurado,
            borderColor: coresEnd.apurado,
            borderWidth: 1
        }, {
            label: 'Meta',
            data: dadosMeta,
            backgroundColor: coresEnd.meta,
            borderColor: coresEnd.meta,
            borderWidth: 1
        }];

        datasets.forEach(function(ds, index) {
            ds.pointStyle = 'rect';
            ds.pointBackgroundColor = ds.backgroundColor;
            ds.pointBorderColor = ds.backgroundColor;
            ds.pointBorderWidth = 0;
        });

        // --- SEGURANÇA ADICIONAL: Verificar se o elemento existe ---
        var canvasElement = document.getElementById('graficoResultado');
        if (!canvasElement) return;

        var ctx = canvasElement.getContext('2d');

        if (chartEnd) {
            chartEnd.destroy();
            chartEnd = null;
        }

        chartEnd = new Chart(ctx, {
            type: desiredType,
            data: {
                labels: anosPresentes,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: {
                    duration: 700,
                    easing: 'easeInOutQuad'
                },
                scales: {
                    x: {
                        display: true,
                        offset: true,
                        grid: {
                            offset: true
                        },
                        ticks: {
                            color: '#0E2B69',
                            font: {
                                size: 16,
                                weight: 800,
                                family: 'Roboto Flex, sans-serif',
                                lineHeight: 1.8
                            },
                            padding: 6,
                            maxRotation: 0,
                            autoSkip: false
                        }
                    },
                    y: {
                        display: true,
                        position: 'right',
                        min: scaleMin,
                        max: scaleMax,
                        ticks: {
                            callback: function(value) {
                                var scaled = value / divisorEscala;
                                return scaled.toLocaleString('pt-BR', {
                                    minimumFractionDigits: 2,
                                    maximumFractionDigits: 2
                                }) + unidadeEscala;
                            },
                            color: '#0E2B69',
                            font: {
                                size: 14,
                                family: 'Roboto Flex, sans-serif'
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top',
                        labels: {
                            usePointStyle: true
                        }
                    },
                    tooltip: {
                        enabled: true,
                        callbacks: {
                            label: function(context) {
                                var raw = context.raw || 0;
                                var scaled = raw / divisorEscala;
                                return context.dataset.label + ': ' +
                                    scaled.toLocaleString('pt-BR', {
                                        minimumFractionDigits: 2,
                                        maximumFractionDigits: 2
                                    }) + unidadeEscala;
                            }
                        }
                    },
                    datalabels: {
                        anchor: 'end',
                        align: function(context) {
                            return context.raw < 0 ? 'bottom' : 'top';
                        },
                        formatter: function(value) {
                            if (value === null) return '';
                            var scaled = value / divisorEscala;
                            return scaled.toLocaleString('pt-BR', {
                                minimumFractionDigits: 2,
                                maximumFractionDigits: 2
                            }) + unidadeEscala;
                        },
                        color: '#000',
                        font: {
                            weight: 'bold'
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    data.dadosGraficoEnd = [];
    data.anos = [];
    // O ano é lido do input enviado pelo Client Script
    var anoFiltro = input.ano || "";
   
    // --- 1. Busca e Popula os Anos Disponíveis (para o filtro) ---
    var grAnos = new GlideAggregate('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
    grAnos.addAggregate('COUNT');
    grAnos.groupBy('u_ano');
    grAnos.orderBy('u_ano');
    grAnos.query();
   
    while (grAnos.next()) {
        data.anos.push(grAnos.getValue('u_ano').toString());
    }
    data.anos = Array.from(new Set(data.anos));
    data.anos.sort();
    // --- 2. Busca os Dados ---
    var grEnd = new GlideRecord('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
   
    // Lógica de Filtro: se um ano específico for selecionado, filtra por ele.
    if (anoFiltro !== "" && anoFiltro.toLowerCase() !== "todos") {
        grEnd.addQuery('u_ano', anoFiltro);
    }
    // Se 'anoFiltro' for "Todos" ou vazio, NENHUM filtro é aplicado,
    // buscando todos os dados disponíveis.
   
    // Ordena
    grEnd.orderBy('u_ano');
    grEnd.query();
    var listaEnd = [];
    while (grEnd.next()) {
        var ano = grEnd.getValue('u_ano').toString();
        var apurado = grEnd.getValue('valor_apurado_resultado_primario') || '0';
        var meta = grEnd.getValue('meta_resultado_primario') || '0';
       
        listaEnd.push({
            ano: ano,
            apurado: apurado,
            meta: meta
        });
    }
   
    data.dadosGraficoEnd = listaEnd;
})();
